mapper.select:
SELECT

FROM dz_task_dist_list_add t
LEFT JOIN sys_user s ON s.user_id = t.reporter_id
WHERE t.task_id = #{taskId}
AND t.user_id = #{userId}

mapper.update:
UPDATE dz_task_dist_list_add

    remark = #{entity.remark},
    reporter_id = #{entity.reportUserId}

WHERE task_id = #{entity.taskId}
AND user_id = #{entity.userId}

mapper.delete:
DELETE
FROM dz_task_dist_list_add
WHERE task_id = #{taskId}
  AND user_id = #{userId}
